CREATE COLUMN TABLE "TEST_AP"."OCRP" ("CrTypeCode" SMALLINT CS_INT NOT NULL , "CrTypeName" NVARCHAR(30) NOT NULL , "CreditCard" SMALLINT CS_INT, "DueTerms" NVARCHAR(8), "MinCredit" DECIMAL(21,6) CS_FIXED, "MinToPay" DECIMAL(21,6) CS_FIXED, "MaxValid" DECIMAL(21,6) CS_FIXED, "InstalMent" NVARCHAR(1) DEFAULT 'N', "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("CrTypeCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCRP_NAME" ON "TEST_AP"."OCRP" ( "CrTypeName" ASC );
CREATE INDEX "OCRP_CRED_CODE" ON "TEST_AP"."OCRP" ( "CreditCard" ASC );
CREATE INDEX "OCRP_INSTALMENT" ON "TEST_AP"."OCRP" ( "InstalMent" ASC )